const VOCAB_FORMAT={name:'Picture Vocabulary',icon:'📸',mode:'SOLO',input:'image',color:'#519ac8',rule:'Look at the picture and choose the matching word. Earn 100 points for each correct answer. Listen reads the question and word choices aloud.'};
ACTIVITIES.picturevocab=VOCAB_FORMAT;FORMATS.picturevocab={...VOCAB_FORMAT,description:VOCAB_FORMAT.rule,instructions:VOCAB_FORMAT.rule+' Teachers: choose a built-in picture or upload your own, then edit the correct word and wrong choices.'};
for(const [subject,grade,topic,keys] of [['english',2,'Everyday words',['umbrella','backpack','bicycle','ladder','helmet','bridge']],['english',7,'Scientific equipment',['microscope','magnet','thermometer','beaker']],['science',5,'Lab vocabulary',['microscope','magnet','thermometer','beaker']],['ict',7,'Computer equipment',['keyboard','mouse','monitor','headphones']]])GAMES.push({id:subject+'-'+grade+'-picturevocab',format:'picturevocab',subject,grade,topic,title:'Picture Vocabulary: '+topic,minutes:'5–10',items:keys.map((key,i)=>({prompt:'Which word matches this picture?',answer:VOCAB_ART[key].name.toLowerCase(),options:[keys[(i+1)%keys.length],keys[(i+2)%keys.length]].map(k=>VOCAB_ART[k].name.toLowerCase()),vocabArt:key,hint:'',explanation:''}))});
function vocabPicture(q){if(q.image)return '<img src="'+q.image+'" alt="Picture clue" draggable="false">';const art=VOCAB_ART[q.vocabArt];return art?'<svg viewBox="0 0 400 400" role="img" aria-label="Vocabulary picture clue"><rect width="400" height="400" fill="#e3f4fc"/><circle cx="310" cy="75" r="60" fill="#fff2bf" opacity=".65"/><ellipse cx="200" cy="353" rx="150" ry="20" fill="#84abc5" opacity=".2"/><g stroke="#42516d" stroke-width="6" stroke-linejoin="round" stroke-linecap="round">'+art.body+'</g></svg>':'<p>Choose or upload a picture.</p>';}
function vocabFields(item){const extra={};if(item.vocabArt!==undefined){if(!Object.hasOwn(VOCAB_ART,item.vocabArt))throw Error('Choose a valid vocabulary illustration.');extra.vocabArt=item.vocabArt;}return extra;}
function vocabValidate(items){if(items.some(q=>!q.image&&!q.vocabArt))throw Error('Choose or upload a picture for every vocabulary question.');}
function vocabEditorRows(){document.querySelectorAll('[data-row]').forEach(row=>{const i=Number(row.dataset.row),q=draft.items[i];row.insertAdjacentHTML('beforeend','<div class="vocab-edit-preview">'+vocabPicture(q)+'</div><div class="vocab-image-tools"><label>Built-in picture<select data-vocab-preset><option value="">'+(q.image?'Uploaded picture':'Choose a picture')+'</option>'+Object.entries(VOCAB_ART).map(([key,art])=>'<option value="'+key+'" '+(!q.image&&q.vocabArt===key?'selected':'')+'>'+art.name+'</option>').join('')+'</select></label><label>Upload your picture<input type="file" data-vocab-upload accept="image/png,image/jpeg,image/webp"></label></div><p class="mode-help">Choose a picture, then set its correct word and the other word choices above. Uploaded pictures are included when you save or download this lesson.</p>');row.querySelector('[data-vocab-preset]').onchange=e=>{if(!e.target.value)return;q.vocabArt=e.target.value;delete q.image;dirty=true;renderRows();};row.querySelector('[data-vocab-upload]').onchange=async e=>{const owner=draft;try{const image=await actUpload(e.target.files[0]);if(owner!==draft||draft.items[i]!==q)return;q.image=image;delete q.vocabArt;dirty=true;renderRows();}catch(err){notify(err.message);}};});}
function renderVocab(){const s=game.session,q=current(),feedback=s.phase==='feedback',complete=s.round+(feedback?1:0);$('.player-bottom>span').textContent='Look at the picture · choose the word';$('#arena').innerHTML='<section class="vocab-game"><div class="vocab-top"><h2>'+esc(q.prompt)+'</h2><button class="vocab-listen" data-mode-action="act-vocab-listen" '+(!('speechSynthesis' in window)?'disabled':'')+' aria-label="Read question and choices aloud">🔊 <span>Listen</span></button></div><div class="vocab-main"><div class="vocab-picture">'+vocabPicture(q)+'</div><div class="vocab-choices">'+game.choices.map((word,i)=>'<button class="vocab-choice '+(feedback&&word===q.answer?'vocab-correct':feedback&&s.vocabChoice===i?'vocab-incorrect':'')+'" data-mode-action="act-vocab-answer" data-value="'+i+'" '+(feedback?'disabled':'')+'><span>'+esc(word)+'</span>'+(feedback&&word===q.answer?'<b aria-label="Correct answer">✓</b>':feedback&&s.vocabChoice===i?'<b aria-label="Incorrect answer">✕</b>':'')+'</button>').join('')+'</div></div><div class="vocab-feedback" role="status">'+(feedback?'<strong>'+(game.feedbackGood?'You got it!':'The word is '+esc(q.answer)+'.')+'</strong>'+ (q.explanation?'<span>'+esc(q.explanation)+'</span>':'')+actButton('next',complete===game.items.length?'See results →':'Next picture →'):'<span>Look carefully. Take your time.</span>')+'</div><div class="vocab-bottom"><span>Picture '+(s.round+1)+' / '+game.items.length+'</span><div class="vocab-progress" role="progressbar" aria-label="Pictures completed" aria-valuemin="0" aria-valuemax="'+game.items.length+'" aria-valuenow="'+complete+'"><i style="width:'+(complete/game.items.length*100)+'%"></i></div><strong>⭐ '+game.score+'</strong></div></section>';$('#arena').classList.add('activity-arena');}
function handleVocab(button){const s=game.session,a=button.dataset.modeAction,n=Number(button.dataset.value);if(game.done||ui.view!=='player'||button.disabled)return;if(a==='act-vocab-listen'){if(!('speechSynthesis' in window))return;const speech=new SpeechSynthesisUtterance(s.phase==='feedback'?current().answer:current().prompt+'. '+game.choices.join('. '));speech.lang=game.lesson.subject==='russian'?'ru-RU':game.lesson.subject==='kyrgyz'?'ky-KG':'en-GB';speech.rate=.85;speechSynthesis.cancel();speechSynthesis.speak(speech);return;}if(a==='act-next'&&s.phase==='feedback'){window.speechSynthesis?.cancel();actNext();renderGame();return;}if(a!=='act-vocab-answer'||s.phase!=='question'||!Number.isInteger(n)||game.choices[n]===undefined)return;s.vocabChoice=n;actScore(game.choices[n]===current().answer);renderGame();}
document.addEventListener('click',e=>{if(e.target.closest('#edit-again,#restart,[data-replay]'))window.speechSynthesis?.cancel();});window.addEventListener('pagehide',()=>window.speechSynthesis?.cancel());
